  const rows = await queryRows<{ n: number }>(
    ctx,
    "SELECT count() AS n FROM analytics.metrics_daily",
  );
  const count = Number(rows[0]?.n ?? 0);
  const passed = count > 0;
  return {
    passed,
    message: passed ? "Metrics daily has rows." : "Metrics daily is empty.",
    details: { count },
  };
