export CLICKHOUSE_URL="${CLICKHOUSE_URL:-http://localhost:8123}"; node -e "
const { createClient } = require('/opt/dec-bench/eval-core/node_modules/@clickhouse/client');
const client = createClient({ url: process.env.CLICKHOUSE_URL });
(async () => {
  const r1 = await client.query({ query: \"SELECT count() AS n FROM system.tables WHERE database = 'analytics' AND name = 'metrics_daily'\", format: 'JSONEachRow' });
  console.log('table exists', (await r1.json())[0]);
  const r2 = await client.query({ query: \"SELECT count() AS n FROM analytics.metrics_daily\", format: 'JSONEachRow' });
  console.log('row count', (await r2.json())[0]);
  const r3 = await client.query({ query: \"SELECT name FROM system.columns WHERE database = 'analytics' AND table = 'metrics_daily'\", format: 'JSONEachRow' });
  console.log('columns', await r3.json());
  const r4 = await client.query({ query: \"SELECT conversion_rate AS v FROM analytics.metrics_daily WHERE conversion_rate IS NOT NULL LIMIT 1\", format: 'JSONEachRow' });
  const row = (await r4.json())[0];
  const rate = Number(row?.v);
  console.log('conversion sample', rate, 'in range', rate >= 0 && rate <= 1);
  const t0 = Date.now();
  await client.query({ query: 'SELECT * FROM analytics.metrics_daily LIMIT 10', format: 'JSONEachRow' });
  console.log('select star ms', Date.now() - t0);
  await client.close();
})();
"

